import{_ as e,o as d,c as a,aj as o}from"./chunks/framework.CC5f6t99.js";const p=JSON.parse('{"title":"tsParticles Errors","description":"","frontmatter":{},"headers":[],"relativePath":"de/errors/index.md","filePath":"de/errors/index.md"}'),r={name:"de/errors/index.md"};function i(s,t,n,c,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="tsparticles-errors" tabindex="-1">tsParticles Errors <a class="header-anchor" href="#tsparticles-errors" aria-label="Permalink to &quot;tsParticles Errors&quot;">​</a></h1><p><strong>tsParticles</strong> reports failures through stable, human-readable <strong>error codes</strong> instead of embedding full message strings in every delivered bundle.</p><p>Depending on the build, an error is surfaced in one of two ways:</p><ul><li><strong>Development / non-minified builds</strong> throw the full, formatted English message, e.g. <code>Invalid HDR &quot;peakNits&quot; value: expected a positive number, got &quot;NaN&quot;</code>.</li><li><strong>Minified / production builds</strong> throw only a compact code plus a link to this page, e.g. <code>[tsParticles Error TSP-1203] https://particles.js.org/errors/#TSP-1203</code>.</li></ul><p>The code is stable and never reused after a release: if you see <code>TSP-xxxx</code>, the explanation below is the authoritative one.</p><h2 id="reading-an-error-code" tabindex="-1">Reading an error code <a class="header-anchor" href="#reading-an-error-code" aria-label="Permalink to &quot;Reading an error code&quot;">​</a></h2><p>A code has the shape <code>TSP-&lt;area&gt;&lt;serial&gt;</code>. The first numbers identify the area:</p><table tabindex="0"><thead><tr><th>Range</th><th>Area</th></tr></thead><tbody><tr><td><code>TSP-100x</code></td><td>Engine core (version, particle, plugin registration)</td></tr><tr><td><code>TSP-110x</code></td><td>Canvas / OffscreenCanvas</td></tr><tr><td><code>TSP-120x</code></td><td>Options validation</td></tr><tr><td><code>TSP-200x</code></td><td>Image shape</td></tr><tr><td><code>TSP-210x</code></td><td>GIF shape</td></tr><tr><td><code>TSP-300x</code></td><td>Polygon mask plugin</td></tr><tr><td><code>TSP-310x</code></td><td>Emitters + emitters shapes</td></tr><tr><td><code>TSP-320x</code></td><td>Interactivity + base mover</td></tr><tr><td><code>TSP-400x</code></td><td>Particle interactions (collisions)</td></tr></tbody></table><p>Some messages contain placeholders such as <code>{0}</code> or <code>{1}</code>. They are replaced at runtime with contextual values (versions, image names, option values). In production builds those values never appear — the compact code + link is shown instead.</p><h2 id="error-catalog" tabindex="-1">Error catalog <a class="header-anchor" href="#error-catalog" aria-label="Permalink to &quot;Error catalog&quot;">​</a></h2><p>The message column shows the development message as emitted by <code>getErrorMessage()</code>; <code>{0}</code>, <code>{1}</code> denote the positional arguments.</p><h3 id="engine" tabindex="-1">Engine <a class="header-anchor" href="#engine" aria-label="Permalink to &quot;Engine&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Message</th></tr></thead><tbody><tr><td><a id="TSP-1001"></a><code>TSP-1001</code></td><td>The tsParticles version is different from the loaded plugins version. Engine version: <code>{0}</code>. Plugin version: <code>{1}</code></td></tr><tr><td><a id="TSP-1002"></a><code>TSP-1002</code></td><td>a valid position cannot be found for particle</td></tr><tr><td><a id="TSP-1003"></a><code>TSP-1003</code></td><td>Register plugins can only be done before calling tsParticles.load()</td></tr><tr><td><a id="TSP-1101"></a><code>TSP-1101</code></td><td>OffscreenCanvas is required but not supported by this browser</td></tr><tr><td><a id="TSP-1102"></a><code>TSP-1102</code></td><td>OffscreenCanvas transfer failed</td></tr><tr><td><a id="TSP-1201"></a><code>TSP-1201</code></td><td>Invalid HDR <code>enable</code> value: expected a boolean, got <code>{0}</code></td></tr><tr><td><a id="TSP-1202"></a><code>TSP-1202</code></td><td>Invalid HDR <code>mode</code> value: expected one of <code>{0}</code>, got <code>{1}</code></td></tr><tr><td><a id="TSP-1203"></a><code>TSP-1203</code></td><td>Invalid HDR <code>peakNits</code> value: expected a positive number, got <code>{0}</code></td></tr></tbody></table><h3 id="image-shape" tabindex="-1">Image shape <a class="header-anchor" href="#image-shape" aria-label="Permalink to &quot;Image shape&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Message</th></tr></thead><tbody><tr><td><a id="TSP-2001"></a><code>TSP-2001</code></td><td>No images collection found</td></tr><tr><td><a id="TSP-2002"></a><code>TSP-2002</code></td><td>No image source provided</td></tr><tr><td><a id="TSP-2003"></a><code>TSP-2003</code></td><td><code>{0}</code> not found</td></tr><tr><td><a id="TSP-2004"></a><code>TSP-2004</code></td><td>Image shape not initialized</td></tr></tbody></table><h3 id="gif-shape" tabindex="-1">GIF shape <a class="header-anchor" href="#gif-shape" aria-label="Permalink to &quot;GIF shape&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Message</th></tr></thead><tbody><tr><td><a id="TSP-2101"></a><code>TSP-2101</code></td><td>not a supported GIF file</td></tr><tr><td><a id="TSP-2102"></a><code>TSP-2102</code></td><td>GIF frame size is to large</td></tr><tr><td><a id="TSP-2103"></a><code>TSP-2103</code></td><td>error while parsing frame <code>{0}</code> &quot;{1}&quot;</td></tr><tr><td><a id="TSP-2104"></a><code>TSP-2104</code></td><td>could not create offscreen canvas context</td></tr></tbody></table><h3 id="polygon-mask-plugin" tabindex="-1">Polygon mask plugin <a class="header-anchor" href="#polygon-mask-plugin" aria-label="Permalink to &quot;Polygon mask plugin&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Message</th></tr></thead><tbody><tr><td><a id="TSP-3001"></a><code>TSP-3001</code></td><td>No polygon found, you need to specify SVG url in config.</td></tr><tr><td><a id="TSP-3002"></a><code>TSP-3002</code></td><td>Error occurred during polygon mask download</td></tr><tr><td><a id="TSP-3003"></a><code>TSP-3003</code></td><td>No polygon data loaded.</td></tr></tbody></table><h3 id="emitters-emitters-shapes" tabindex="-1">Emitters + emitters shapes <a class="header-anchor" href="#emitters-emitters-shapes" aria-label="Permalink to &quot;Emitters + emitters shapes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Message</th></tr></thead><tbody><tr><td><a id="TSP-3101"></a><code>TSP-3101</code></td><td>tsParticles Emitters Plugin is not loaded</td></tr><tr><td><a id="TSP-3102"></a><code>TSP-3102</code></td><td>No 2d context available</td></tr><tr><td><a id="TSP-3103"></a><code>TSP-3103</code></td><td>No path data available</td></tr></tbody></table><h3 id="interactivity-base-mover" tabindex="-1">Interactivity + base mover <a class="header-anchor" href="#interactivity-base-mover" aria-label="Permalink to &quot;Interactivity + base mover&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Message</th></tr></thead><tbody><tr><td><a id="TSP-3201"></a><code>TSP-3201</code></td><td>tsParticles Interactivity Plugin is not loaded</td></tr><tr><td><a id="TSP-3202"></a><code>TSP-3202</code></td><td>Click handlers can only be set after calling tsParticles.load()</td></tr><tr><td><a id="TSP-3203"></a><code>TSP-3203</code></td><td>tsParticles Base Mover is not loaded</td></tr></tbody></table><h3 id="particle-interactions" tabindex="-1">Particle interactions <a class="header-anchor" href="#particle-interactions" aria-label="Permalink to &quot;Particle interactions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Message</th></tr></thead><tbody><tr><td><a id="TSP-4001"></a><code>TSP-4001</code></td><td>Particle is overlapping and can&#39;t be placed</td></tr></tbody></table>',25)])])}const g=e(r,[["render",i]]);export{p as __pageData,g as default};
